-- Approved exception: Hub + every A2A spoke share Hub client credentials
-- and live access/refresh tokens in accounts (common space). CRM does not
-- own other accounts.* tables. Prisma does not map this model (accounts is
-- not in the CRM datasource schemas list).
-- Split-DB copy: scripts/sql/accounts_a2a_spoke_clients.sql

CREATE SCHEMA IF NOT EXISTS "accounts";

CREATE TABLE IF NOT EXISTS "accounts"."a2a_spoke_clients" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "a2a_server_name" VARCHAR(64) NOT NULL,
  "client_id" VARCHAR(128) NOT NULL,
  "client_secret" TEXT NOT NULL,
  "access_token" TEXT,
  "access_expires_at" TIMESTAMPTZ,
  "refresh_token" TEXT,
  "refresh_expires_at" TIMESTAMPTZ,
  "skill_version" VARCHAR(64),
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT "a2a_spoke_clients_server_unique" UNIQUE ("a2a_server_name"),
  CONSTRAINT "a2a_spoke_clients_client_unique" UNIQUE ("client_id")
);

COMMENT ON TABLE "accounts"."a2a_spoke_clients" IS
  'One Hub OAuth client per A2A spoke. Hub SELECTs access_token; the spoke UPDATEs access+refresh after POST /token.';
